class Solution {
    public int jobScheduling(int[] startTime,int[] endTime,int[] profit){
        int n=startTime.length;
        int[][] jobs=new int[n][3];
        for(int i=0;i<n;i++)jobs[i]=new int[]{
            startTime[i],endTime[i],profit[i]
        };
        Arrays.sort(jobs,Comparator.comparingInt(job->job[0]));
        int[] starts=new int[n],dp=new int[n+1];
        for(int i=0;i<n;i++)starts[i]=jobs[i][0];
        for(int i=n-1;i>=0;i--){
            int next=lowerBound(starts,jobs[i][1]);
            dp[i]=Math.max(dp[i+1],jobs[i][2]+dp[next]);
        }
        return dp[0];
    }
    private int lowerBound(int[] values,int target){
        int left=0,right=values.length;
        while(left<right){
            int middle=(left+right)/2;
            if(values[middle]<target)left=middle+1;
            else right=middle;
        }
        return left;
    }
}

